/* Profile-only extension of the existing authenticated portal workflows. */
function profileMissing(owner=false){const p=(owner?myEmployer:myCandidate)||{},q=owner?p:privateProfile||{};const checks=owner?[['Full name',p?.contact_name],['Photo',p?.profile_photo_path],['Mobile',p?.mobile],['Email',p?.email],['City',p?.city],['State',p?.state],['Introduction',p?.description],['Salon name',p?.salon_name],['Address',p?.address]]:[['Full name',p.full_name],['Photo',q.photo_path],['Mobile',q.mobile],['Email',q.email],['City',p.city],['State',p.state],['Introduction',p.bio],['Skills',p.skills?.length],['Experience',p.experience_years!=null],['Qualification',p.qualification],['Languages',p.languages?.length],['Preferred location',p.preferred_locations?.length],['Expected salary',Number(p.expected_salary)>0],['Joining availability',p.availability]];return {missing:checks.filter(([,v])=>!v).map(([k])=>k),total:checks.length}}
function profileCompletion(owner=false){const {missing,total}=profileMissing(owner),exists=owner?myEmployer:myCandidate,percent=exists?Math.floor((total-missing.length)*100/total):0;return `<div class="profile-completion"><strong>Saved profile: ${percent}% complete</strong><progress value="${percent}" max="100" aria-label="Saved profile completion"></progress><p>${missing.length?'Complete: '+e(missing.join(', ')):'Your profile is complete.'}</p></div>`}
function photoPanel(path,owner){return `<section class="profile-photo-panel" data-photo-panel><h2>Profile Photo</h2><div class="photo-preview"><span class="profile-avatar" role="img" aria-label="Default profile avatar">◉</span><img hidden alt="Your profile photo"><button type="button" class="text-link" data-photo-action="preview" hidden>Preview photo</button></div><p>JPG, PNG or WebP · maximum 5 MB. Save profile to apply changes.</p><label class="secondary photo-file">Upload / Choose Photo from Gallery<input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></label><label class="secondary photo-file">Take Photo using Camera<input type="file" name="camera_photo" capture="user" accept="image/jpeg,image/png,image/webp"></label><div class="form-actions"><button type="button" class="secondary" data-photo-action="change">Change Photo</button><button type="button" class="text-link" data-photo-action="remove">Remove Photo</button><button type="button" class="secondary" data-photo-action="retry" hidden>Retry upload</button></div><progress hidden max="100" value="0" aria-label="Photo upload progress"></progress><p data-photo-status role="status" aria-live="polite"></p><input type="hidden" name="${owner?'profile_photo_path':'photo_path'}" value="${e(path||'')}"></section>`}
function photoRender(form,url){const panel=form.querySelector('[data-photo-panel]'),img=panel.querySelector('img');img.hidden=!url;panel.querySelector('.profile-avatar').hidden=!!url;panel.querySelector('[data-photo-action=preview]').hidden=!url;if(url)img.src=url;else img.removeAttribute('src')}
async function initPhoto(form,owner){form._photoOwner=owner;const path=form.elements[owner?'profile_photo_path':'photo_path'].value;if(path)try{const url=await signedFile('nexora-job-private',path);if(form.isConnected&&!form._photoFile&&form.elements[owner?'profile_photo_path':'photo_path'].value===path)photoRender(form,url)}catch{form.querySelector('[data-photo-status]').textContent='Saved photo could not load. Use Retry.';form.querySelector('[data-photo-action=retry]').hidden=false}}
const originalCandidateForm=candidateForm;
candidateForm=function(){originalCandidateForm();const form=$('#candidate-form');if(!form)return;const path=form.elements.photo_path.value;form.elements.photo.closest('label').remove();form.elements.photo_path.remove();form.insertAdjacentHTML('afterbegin',photoPanel(path,false)+profileCompletion(false));form.querySelector('[data-wizard-step="1"] legend').textContent='Personal Information';form.querySelector('[data-wizard-step="3"] legend').textContent='Professional Information';form.querySelector('[data-wizard-step="4"] legend').textContent='Resume and Portfolio';const grid=form.querySelector('[data-wizard-step="3"] .form-grid');grid.querySelector('[name=experience_years]').closest('label').insertAdjacentHTML('beforebegin','<h3 class="profile-subheading">Skills and Experience</h3>');grid.querySelector('[name=preferred_locations]').closest('label').insertAdjacentHTML('beforebegin','<h3 class="profile-subheading">Job Preferences</h3>');form.insertAdjacentHTML('beforeend','<button type="button" class="secondary" data-profile-cancel>Cancel</button>');initPhoto(form,false)};
const originalEmployerForm=employerForm;
employerForm=function(){originalEmployerForm();const form=$('#employer-form');if(!form)return;const d=safeRead(draftKey('employer'),null)||myEmployer||{};form.insertAdjacentHTML('afterbegin',photoPanel(d.profile_photo_path,true)+profileCompletion(true)+'<h2>Personal Information</h2>');form.elements.address.closest('label').insertAdjacentHTML('beforebegin','<h2>Professional Information</h2>');form.insertAdjacentHTML('beforeend','<button type="button" class="secondary" data-profile-cancel>Cancel</button>');initPhoto(form,true)};
async function uploadProfilePhoto(form){if(!form._photoFile)return '';const file=form._photoFile;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||!file.size||file.size>5242880)throw Error('Choose a JPG, PNG or WebP image up to 5 MB.');await refreshIfNeeded();const ext={'image/jpeg':'jpg','image/png':'png','image/webp':'webp'}[file.type],path=session.user.id+'/photo/'+crypto.randomUUID()+'.'+ext,panel=form.querySelector('[data-photo-panel]'),progress=panel.querySelector('progress'),status=panel.querySelector('[data-photo-status]');progress.hidden=false;progress.value=0;status.textContent='Uploading photo…';panel.querySelector('[data-photo-action=retry]').hidden=true;
 try{await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',cfg.supabaseUrl+'/storage/v1/object/nexora-job-private/'+path);xhr.setRequestHeader('apikey',cfg.supabaseKey);xhr.setRequestHeader('Authorization','Bearer '+session.access_token);xhr.setRequestHeader('Content-Type',file.type);xhr.timeout=60000;xhr.upload.onprogress=ev=>{if(ev.lengthComputable){progress.value=ev.loaded/ev.total*100;status.textContent='Uploading photo '+Math.round(progress.value)+'%'}};xhr.onload=()=>xhr.status>=200&&xhr.status<300?resolve():reject(Error('Photo upload failed. Retry.'));xhr.onerror=()=>reject(Error('Connection failed. Retry upload.'));xhr.ontimeout=xhr.onerror;xhr.send(file)});form.elements[form._photoOwner?'profile_photo_path':'photo_path'].value=path;form._photoFile=null;persistForm(form);status.textContent='Photo uploaded. Save profile to apply the change.';return path}catch(err){status.textContent=err.message;panel.querySelector('[data-photo-action=retry]').hidden=false;throw err}finally{progress.hidden=true}}
document.addEventListener('change',ev=>{const n=ev.target,form=n.form;if(!form||form.dataset.busy==='true'||!['photo','camera_photo'].includes(n.name)||!form.querySelector('[data-photo-panel]'))return;const file=n.files[0];if(!file)return;const panel=form.querySelector('[data-photo-panel]');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>5242880||!file.size){panel.querySelector('[data-photo-status]').textContent='Choose JPG, PNG or WebP up to 5 MB.';n.value='';return}if(form._previewURL)URL.revokeObjectURL(form._previewURL);form._photoFile=file;form._previewURL=URL.createObjectURL(file);photoRender(form,form._previewURL);panel.querySelector('[data-photo-status]').textContent='Preview ready. Save profile to upload.'});
document.addEventListener('click',async ev=>{const n=ev.target.closest('[data-photo-action],[data-profile-cancel]');if(!n)return;const form=n.closest('form');if(form.dataset.busy==='true')return;if(n.hasAttribute('data-profile-cancel')){localStorage.removeItem(draftKey(form.dataset.draft));if(form._previewURL)URL.revokeObjectURL(form._previewURL);$('#dialog').close();return}const action=n.dataset.photoAction;if(action==='change')return form.elements.photo.click();if(action==='preview'){const img=form.querySelector('[data-photo-panel] img');const dialog=document.createElement('dialog');dialog.className='photo-preview-dialog';dialog.innerHTML=`<img alt="Profile photo preview"><button type="button" class="secondary">Close</button>`;dialog.querySelector('img').src=img.src;dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove());document.body.append(dialog);dialog.showModal();return}if(action==='remove'){form._photoFile=null;form.elements[form._photoOwner?'profile_photo_path':'photo_path'].value='';form.elements.photo.value='';form.elements.camera_photo.value='';photoRender(form,'');persistForm(form);form.querySelector('[data-photo-status]').textContent='Photo removed from this edit. Save to confirm.';return}if(action==='retry'){n.disabled=true;form.dataset.busy='true';try{if(form._photoFile)await uploadProfilePhoto(form);else await initPhoto(form,form._photoOwner)}catch(err){toast(err.message)}finally{n.disabled=false;delete form.dataset.busy}}});
const originalProfileDashboard=dashboard;
dashboard=async function(epoch){await originalProfileDashboard(epoch);if(dashboardTab!=='overview'||epoch!==routeEpoch)return;const cards=$$('#dashboard-content .dashboard-grid > article');for(const [i,owner] of [false,true].entries()){const card=cards[i];if(!card)continue;card.insertAdjacentHTML('afterbegin',profileCompletion(owner));const path=owner?myEmployer?.profile_photo_path:privateProfile?.photo_path;if(path)try{const url=await signedFile('nexora-job-private',path);if(card.isConnected)card.insertAdjacentHTML('afterbegin',`<img class="profile-saved-avatar" src="${e(url)}" alt="Saved profile photo">`)}catch{if(card.isConnected)card.insertAdjacentHTML('afterbegin','<p>Photo unavailable. Open Edit profile to retry.</p>')}}};
